 out=Path(__file__).resolve().parents[2]/'reports/math-book/research-audit.json';d=audit();out.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print({k:d[k] for k in ['reviewedSources','rawCount','duplicateCount','rejectedCount','retainedSourcePatterns']})
